def _new250_path(path):
    if (not isinstance(path, str) or not path or path.startswith('/')
            or any(c in path for c in ('\\', '\0', ':'))
            or any(p in ('', '.', '..') for p in path.split('/'))):
        raise ValueError('NEW250 noncanonical path')
    return path


def _new250_identity(body):
    return (hashlib.sha1(b'blob ' + str(len(body)).encode() + b'\0' + body).hexdigest(),
            hashlib.sha256(body).hexdigest(), len(body))


def _new250_json(body):
    def pairs(items):
        result = {}
        for key, value in items:
            if key in result:
                raise ValueError('NEW250 duplicate JSON key')
            result[key] = value
        return result
    def invalid(value):
        raise ValueError('NEW250 invalid numeric constant')
    return json.loads(body, object_pairs_hook=pairs, parse_constant=invalid)


def _new250_identity_fields(row):
    if (type(row['bytes']) is not int or row['bytes'] < 0
            or type(row['blob']) is not str or not re.fullmatch('[0-9a-f]{40}', row['blob'])
            or type(row['sha256']) is not str or not re.fullmatch('[0-9a-f]{64}', row['sha256'])):
        raise ValueError('NEW250 malformed native identity')


def _new250_members_schema(members, total_bytes):
    """Validate complete finite metadata without inventing receiver identities."""
    if type(total_bytes) is not int or total_bytes < 0:
        raise ValueError('NEW250 malformed total byte count')
    if type(members) is not list or not members:
        raise ValueError('NEW250 empty or malformed census')
    paths, ids, offset = set(), set(), 0
    for row in members:
        if type(row) is not dict or set(row) != {'path', 'offset', 'bytes', 'sha256', 'blob', 'public', 'continuations', 'original'}:
            raise ValueError('NEW250 member fields differ')
        _new250_identity_fields(row)
        path = _new250_path(row['path'])
        if path in paths or type(row['offset']) is not int or row['offset'] != offset:
            raise ValueError('NEW250 duplicate path, gap or overlap')
        paths.add(path)
        original = row['original']
        fresh_keys = {'blob', 'bytes', 'commit', 'evidence', 'mode', 'paths', 'source_sha256', 'tree'}
        baseline_keys = {'all_blob_aliases', 'blob', 'commit', 'evidence_type', 'mode', 'path', 'tree', 'type'}
        if type(original) is not dict or set(original) not in (fresh_keys, baseline_keys):
            raise ValueError('NEW250 original preservation schema differs')
        if (original['mode'] != '100644' or original['blob'] != row['blob']
                or any(type(original[key]) is not str or not re.fullmatch('[0-9a-f]{40}', original[key])
                       for key in ('commit', 'tree'))):
            raise ValueError('NEW250 original native coordinate differs')
        if set(original) == fresh_keys:
            if (original['paths'] != [path] or type(original['bytes']) is not int
                    or original['bytes'] != row['bytes'] or original['source_sha256'] != row['sha256']
                    or type(original['evidence']) is not str or not original['evidence'].strip()):
                raise ValueError('NEW250 fresh original preservation coordinate differs')
        elif (original['path'] != path or original['all_blob_aliases'] != [path]
                or original['type'] != 'blob' or type(original['evidence_type']) is not str
                or not original['evidence_type'].strip()):
            raise ValueError('NEW250 baseline original preservation coordinate differs')
        offset += row['bytes']
        if offset > total_bytes:
            raise ValueError('NEW250 slice outside receiver')
        if type(row['public']) is not dict or row['public'].get('repository_path') != path:
            raise ValueError('NEW250 public join differs')
        if type(row['continuations']) is not list:
            raise ValueError('NEW250 continuation domain differs')
        for source in row['continuations']:
            if (type(source) is not dict or type(source.get('id')) is not str
                    or source['id'] in ids or source.get('path') != path):
                raise ValueError('NEW250 duplicate ID or source join differs')
            ids.add(source['id'])
        for role, sha, size in [(row['public'], 'public_sha256', 'public_bytes'),
                                 *[(r, 'sha256', 'bytes') for r in row['continuations']]]:
            if role.get(sha) != row['sha256'] or type(role.get(size)) is not int or role[size] != row['bytes']:
                raise ValueError('NEW250 role byte identity differs')
    for population in (CHECKPOINT_COPY_PATHS, CHECKPOINT_RECORD_COPY_PATHS,
                       CHECKPOINT_CODE_COPY_PATHS, CHECKPOINT_PACKAGE_COPY_PATHS,
                       FORMAL_PROVIDER_PATHS, FORMAL_COPY_PATHS, FORMAL_CONTINUATION_PATHS,
                       FORMAL_SUCCESSOR_PATHS, CONTINUATION_FORMAL_RETARGET_PATHS,
                       ADMIN_RECORD_PATHS, ADMIN_PUBLIC_GUIDE_PATHS, DIGEST_RECORD_PATHS,
                       ADMISSION_RECORD_PATHS, SUCCESSOR_INPUT_PATHS, GENERATED_FIXTURE_PATHS,
                       SUCCESSOR_READ_BATCH_PATHS, SUCCESSOR_REMAINDER_BATCH_PATHS):
        if paths.intersection(population):
            raise ValueError('NEW250 overlaps another finite provider class')
    if offset != total_bytes or paths != NEW250_PATHS:
        raise ValueError('NEW250 finite byte/path census differs')
    if _formal_row_digest(members) != _formal_row_digest(list(NEW250_MEMBERS)):
        raise ValueError('NEW250 complete finite row binding differs')
    return {row['path']: row for row in members}



def _new250_schema(catalog):
    if type(catalog) is not dict or set(catalog) != {'version', 'receiver', 'members'}:
        raise ValueError('NEW250 catalog fields differ')
    if type(catalog['version']) is not int or catalog['version'] != 1:
        raise ValueError('NEW250 catalog version differs')
    receiver = catalog['receiver']
    if type(receiver) is not dict or set(receiver) != {'blob', 'sha256', 'bytes'}:
        raise ValueError('NEW250 receiver fields differ')
    _new250_identity_fields(receiver)
    return _new250_members_schema(catalog['members'], receiver['bytes'])


class _New250Walk:
    """All opens are descriptor-relative; retained parent edges are rechecked.

    No path-only cache. A snapshot ends only after all file, absence, parent and
    index witnesses have been rechecked. As with ordinary filesystem reads,
    this cannot promise immutability after return against a concurrent writer.
    """
    def __init__(self, root):
        self.fds, self.edges, self.files, self.absent = [], [], [], []
        self.directories = {}
        self.root = None
        try:
            fd = os.open('/', os.O_RDONLY | os.O_DIRECTORY)
            self.fds.append(fd)
            absolute = pathlib.Path(root).absolute()
            for name in absolute.parts[1:]:
                fd = self.directory(fd, name)
            self.root = fd
        except BaseException:
            self.close()
            raise

    def directory(self, parent, name):
        # Reuse only this snapshot's exact anchored parent/name edge. The edge
        # is still checked on every reuse and again before releasing bytes.
        key = (parent, name)
        if key in self.directories:
            fd = self.directories[key]
            current = os.stat(name, dir_fd=parent, follow_symlinks=False)
            held = os.fstat(fd)
            if (current.st_dev, current.st_ino, current.st_mode) != (held.st_dev, held.st_ino, held.st_mode):
                raise ValueError('NEW250 reused directory edge changed')
            return fd
        fd = os.open(name, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=parent)
        self.fds.append(fd)
        self.edges.append((parent, name, fd))
        self.directories[key] = fd
        return fd

    @staticmethod
    def witness(st):
        return tuple(getattr(st, field) for field in
                     ('st_dev', 'st_ino', 'st_mode', 'st_nlink', 'st_size', 'st_mtime_ns', 'st_ctime_ns'))

    def read(self, path, size, optional=False):
        parts = _new250_path(path).split('/')
        fd = self.root
        for name in parts[:-1]:
            try:
                fd = self.directory(fd, name)
            except FileNotFoundError:
                if not optional:
                    raise
                self.absent.append((fd, name))
                return None
        name = parts[-1]
        try:
            leaf = os.open(name, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK, dir_fd=fd)
        except FileNotFoundError:
            if not optional:
                raise
            self.absent.append((fd, name))
            return None
        self.fds.append(leaf)
        before = os.fstat(leaf)
        if (not stat.S_ISREG(before.st_mode) or before.st_nlink != 1
                or before.st_mode & 0o111 or before.st_size != size):
            raise ValueError('NEW250 nonordinary file or size differs')
        chunks, remaining = [], size + 1
        while remaining:
            chunk = os.read(leaf, min(remaining, 65536))
            if not chunk:
                break
            chunks.append(chunk)
            remaining -= len(chunk)
        body = b''.join(chunks)
        if len(body) != size:
            raise ValueError('NEW250 bounded read size differs')
        self.files.append((fd, name, leaf, self.witness(before)))
        return body

    def verify(self):
        for parent, name, fd in self.edges:
            current = os.stat(name, dir_fd=parent, follow_symlinks=False)
            held = os.fstat(fd)
            if (current.st_dev, current.st_ino, current.st_mode) != (held.st_dev, held.st_ino, held.st_mode):
                raise ValueError('NEW250 directory edge changed')
        for parent, name, fd, witness in self.files:
            if (self.witness(os.fstat(fd)) != witness
                    or self.witness(os.stat(name, dir_fd=parent, follow_symlinks=False)) != witness):
                raise ValueError('NEW250 file changed during snapshot')
        for parent, name in self.absent:
            try:
                os.stat(name, dir_fd=parent, follow_symlinks=False)
            except FileNotFoundError:
                continue
            raise ValueError('NEW250 absence changed during snapshot')

    def index(self, paths):
        env = {k: v for k, v in os.environ.items() if not k.startswith('GIT_')}
        env.update(GIT_NO_REPLACE_OBJECTS='1', GIT_NO_LAZY_FETCH='1', GIT_OPTIONAL_LOCKS='0', GIT_CONFIG_NOSYSTEM='1', GIT_ALLOW_PROTOCOL='', GIT_TERMINAL_PROMPT='0',
                   GIT_CONFIG_GLOBAL=os.devnull, GIT_CONFIG_SYSTEM=os.devnull,
                   GIT_CONFIG_COUNT='2', GIT_CONFIG_KEY_0='core.fsmonitor', GIT_CONFIG_VALUE_0='false',
                   GIT_CONFIG_KEY_1='core.untrackedCache', GIT_CONFIG_VALUE_1='false')
        proc = subprocess.run(['git', '--no-replace-objects', '--literal-pathspecs',
                               'ls-files', '--stage', '-z', '--', *sorted(paths)],
                              cwd='/proc/self/fd/' + str(self.root), pass_fds=(self.root,),
                              env=env, capture_output=True, check=False)
        if proc.returncode:
            raise ValueError('NEW250 index unavailable')
        result = {}
        for item in proc.stdout.split(b'\0'):
            if not item:
                continue
            meta, name = item.split(b'\t', 1)
            mode, blob, stage = meta.decode('ascii').split()
            path = name.decode('utf-8')
            if path not in paths or path in result or mode != '100644' or stage != '0':
                raise ValueError('NEW250 index path/mode/stage differs')
            result[path] = blob
        return result

    def close(self):
        for fd in reversed(self.fds):
            os.close(fd)
        self.fds = []
        self.directories = {}


def _new250_snapshot(root):
    if NEW250_CATALOG_IDENTITY is None or not NEW250_PATHS:
        raise ValueError('NEW250 measured production binding not installed')
    names = NEW250_PATHS | {NEW250_CATALOG, NEW250_RECEIVER}
    walk = _New250Walk(root)
    try:
        index = walk.index(names)
        catalog_body = walk.read(NEW250_CATALOG, NEW250_CATALOG_IDENTITY[2])
        if _new250_identity(catalog_body) != NEW250_CATALOG_IDENTITY:
            raise ValueError('NEW250 catalog identity differs')
        catalog = _new250_json(catalog_body)
        members = _new250_schema(catalog)
        receiver = catalog['receiver']
        packed = walk.read(NEW250_RECEIVER, receiver['bytes'])
        if _new250_identity(packed) != (receiver['blob'], receiver['sha256'], receiver['bytes']):
            raise ValueError('NEW250 whole receiver identity differs')
        for path, blob in ((NEW250_CATALOG, NEW250_CATALOG_IDENTITY[0]), (NEW250_RECEIVER, receiver['blob'])):
            if index.get(path) != blob:
                raise ValueError('NEW250 provider must have exact stage0 index')
        bodies, absent = {}, set()
        for path, row in members.items():
            body = packed[row['offset']:row['offset'] + row['bytes']]
            if _new250_identity(body) != (row['blob'], row['sha256'], row['bytes']):
                raise ValueError('NEW250 slice native identity differs')
            original = walk.read(path, row['bytes'], optional=True)
            if original is None:
                absent.add(path)
                if path in index and index[path] != row['blob']:
                    raise ValueError('NEW250 absent original index differs')
            elif original != body or index.get(path) != row['blob']:
                raise ValueError('NEW250 present original bytes/index differs')
            bodies[path] = body
        if walk.index(names) != index:
            raise ValueError('NEW250 index changed during snapshot')
        walk.verify()
        additions = {NEW250_CATALOG: {'path': NEW250_CATALOG, 'kind': 'blob', 'mode': '100644',
                     'git_oid': NEW250_CATALOG_IDENTITY[0], 'bytes': len(catalog_body)},
                     NEW250_RECEIVER: {'path': NEW250_RECEIVER, 'kind': 'blob', 'mode': '100644',
                     'git_oid': receiver['blob'], 'bytes': len(packed)}}
        return bodies, absent, additions
    finally:
        walk.close()


def new250_source_bytes(root, path):
    _new250_path(path)
    if path not in NEW250_PATHS:
        raise ValueError('path outside NEW250 finite class')
    return _new250_snapshot(root)[0][path]


def new250_public_bytes(root, row):
    expected = [m['public'] for m in NEW250_MEMBERS if m['path'] == row.get('repository_path')]
    if len(expected) != 1 or _formal_row_digest(row) != _formal_row_digest(expected[0]):
        raise ValueError('NEW250 complete public role row differs')
    return new250_source_bytes(root, row['repository_path'])


def new250_continuation_bytes(root, row):
    expected = [r for m in NEW250_MEMBERS for r in m['continuations'] if r['id'] == row.get('id')]
    if len(expected) != 1 or _formal_row_digest(row) != _formal_row_digest(expected[0]):
        raise ValueError('NEW250 complete continuation source-ID row differs')
    return new250_source_bytes(root, row['path'])


def new250_validate_rows(rows, continuation=False):
    """Finite equality join, including duplicate IDs and alternate selected aliases."""
    expected = ([r for m in NEW250_MEMBERS for r in m['continuations']] if continuation
                else [m['public'] for m in NEW250_MEMBERS])
    key, pathkey = ('id', 'path') if continuation else ('repository_path', 'repository_path')
    keys = {r[key] for r in expected}
    selected = [r for r in rows if r.get(key) in keys or r.get(pathkey) in NEW250_PATHS]
    if (len(selected) != len(expected) or len({r[key] for r in selected}) != len(expected)
            or {_formal_row_digest(r) for r in selected} != {_formal_row_digest(r) for r in expected}):
        raise ValueError('NEW250 complete selected row domain differs')


def new250_absences(root):
    return _new250_snapshot(root)[1]


def new250_provider_additions(root):
    return _new250_snapshot(root)[2] if NEW250_PATHS else {}


def new250_reader_sources(root, sources):
    selected = {key: row for key, row in sources.items()
                if key in NEW250_READER_ROWS or row.get('path') in NEW250_PATHS}
    if _formal_row_digest(selected) != _formal_row_digest(NEW250_READER_ROWS):
        raise ValueError('NEW250 reader key/path/hash/scope differs')
    bodies = _new250_snapshot(root)[0] if NEW250_PATHS else {}
    return {row['path']: bodies[row['path']] for row in selected.values()}



"""Exact bounded provider. No scholarly, deletion or historical-profile authority."""


def _next250_exact(a, b):
    return json.dumps(a, sort_keys=True, separators=(',', ':'), allow_nan=False) == json.dumps(b, sort_keys=True, separators=(',', ':'), allow_nan=False)


class FiniteSourceProvider:
    def __init__(self, binding, walk, safe_path, identity, parse_json):
        self.binding = json.loads(json.dumps(binding))
        self.walk, self.safe_path = walk, safe_path
        self.identity, self.parse_json = identity, parse_json
        members = self.binding['members']
        self.members = {safe_path(m['path']): m for m in members}
        self.paths = frozenset(self.members)
        self.ids = frozenset(m['sha256'] for m in members)
        if len(self.members) != len(members) or len(self.ids) != len(members):
            raise ValueError('duplicate provider member path or source identity')
        offset = 0
        for m in members:
            if type(m['bytes']) is not int or m['bytes'] < 0 or type(m['offset']) is not int or m['offset'] != offset:
                raise ValueError('provider member size/gap/overlap differs')
            p = m['public']
            if (p.get('repository_path') != m['path'] or p.get('source_sha256') != m['sha256']
                    or p.get('public_sha256') != m['sha256'] or p.get('source_bytes') != m['bytes']
                    or p.get('public_bytes') != m['bytes'] or p.get('role') != 'authored_proof'
                    or p.get('disposition') != 'ADD_EXACT'):
                raise ValueError('provider complete public source identity differs')
            offset += m['bytes']
        self.total_bytes = offset
        provider_paths = [safe_path(self.binding[k]) for k in ('catalog_path', 'receiver_path')]
        if len(set(provider_paths)) != 2 or self.paths.intersection(provider_paths):
            raise ValueError('provider path overlaps member or catalog')

    def candidate(self, row):
        # Domain selection is exact-path only; foreign same-SHA rows are unrelated.
        return row.get('repository_path') in self.paths

    def reject_alias(self, path):
        if isinstance(path, str) and os.path.normpath(path) in self.paths and path not in self.paths:
            raise ValueError('NEXT250 noncanonical selected fallback alias')

    def validate_rows(self, rows):
        selected = [r for r in rows if self.candidate(r)]
        if len(selected) != len(self.members):
            raise ValueError('provider complete row domain differs')
        seen = set()
        for r in selected:
            path = self.safe_path(r.get('repository_path'))
            if path in seen or path not in self.members or not _next250_exact(r, self.members[path]['public']):
                raise ValueError('provider complete public row differs')
            seen.add(path)

    def snapshot(self, root):
        b = self.binding
        if (b['status'] != 'BOUND' or b.get('published_base') is None
                or b['catalog_identity'] is None or b['receiver_identity'] is None
                or b.get('source_universe') is None or b.get('separation_profiles') is None
                or b.get('fallback_reachability') is None or b.get('provisional_input') is None
                or b.get('metadata_policy') is None or b.get('consumer_logic_sha256') is None
                or b.get('reachability_acceptance') is None or b.get('consumer_contexts') is None
                or b.get('reader_rows') is None):
            raise ValueError('NOT_EXECUTABLE: published base and measured provider identities required')
        catalog, receiver = b['catalog_path'], b['receiver_path']
        ci, ri = tuple(b['catalog_identity']), tuple(b['receiver_identity'])
        if ri[2] != self.total_bytes:
            raise ValueError('provider total byte census differs')
        names = self.paths | {catalog, receiver}
        walk = self.walk(root)
        try:
            head = self.verify_contract(walk)
            index = walk.index(names)
            cb = walk.read(catalog, ci[2])
            if self.identity(cb) != ci:
                raise ValueError('provider catalog identity differs')
            expected = {'version': 1, 'members': b['members'], 'receiver_identity': list(ri),
                        'published_base': b['published_base'],
                        'source_universe': b['source_universe'],
                        'separation_profiles': b['separation_profiles'],
                        'fallback_reachability': b['fallback_reachability'],
                        'provisional_input': b['provisional_input'],
                        'metadata_policy': b['metadata_policy'],
                        'consumer_logic_sha256': b['consumer_logic_sha256'],
                        'reachability_acceptance': b['reachability_acceptance'],
                        'consumer_contexts': b['consumer_contexts'], 'reader_rows': b['reader_rows']}
            if not _next250_exact(self.parse_json(cb), expected):
                raise ValueError('provider catalog complete metadata differs')
            packed = walk.read(receiver, ri[2])
            if self.identity(packed) != ri:
                raise ValueError('provider receiver identity differs')
            if index.get(catalog) != ci[0] or index.get(receiver) != ri[0]:
                raise ValueError('provider stage0 identities differ')
            bodies, absent = {}, set()
            for path, m in self.members.items():
                body = packed[m['offset']:m['offset'] + m['bytes']]
                if self.identity(body) != (m['blob'], m['sha256'], m['bytes']):
                    raise ValueError('provider slice identity differs')
                original = walk.read(path, m['bytes'], optional=True)
                if original is None:
                    absent.add(path)
                    if path in index and index[path] != m['blob']:
                        raise ValueError('absent original index differs')
                elif original != body or index.get(path) != m['blob']:
                    raise ValueError('present original bytes/index differs')
                bodies[path] = body
            if walk.index(names) != index:
                raise ValueError('provider index changed during snapshot')
            if self.verify_contract(walk) != head:
                raise ValueError('NEXT250 local HEAD changed')
            walk.verify()
            additions = {p: {'path': p, 'kind': 'blob', 'mode': '100644', 'git_oid': i[0], 'bytes': i[2]}
                         for p, i in ((catalog, ci), (receiver, ri))}
            # New reviewed receipts have finite ordinary ownership too. Historical
            # and provisional provenance inputs do not become provider additions.
            for spec in (b['provisional_input']['qualification'], b['fallback_reachability'],
                         b['reachability_acceptance']):
                path, identity = spec['path'], spec['identity']
                if path in additions:
                    raise ValueError('NEXT250 receipt/provider inventory overlap')
                additions[path] = {'path': path, 'kind': 'blob', 'mode': '100644',
                                   'git_oid': identity[0], 'bytes': identity[2]}
            return bodies, absent, additions
        finally:
            walk.close()

    def verify_contract(self, walk):
        """Verify closed metadata origins without inventing receipt ancestry."""
        b = self.binding
        base = b['published_base']
        if (not isinstance(base, dict) or set(base) != {'commit', 'tree'}
                or any(not isinstance(v, str) or not re.fullmatch('[0-9a-f]{40}', v) for v in base.values())):
            raise ValueError('NEXT250 expected published commit/tree contract missing')
        def git(*args):
            env = {k: v for k, v in os.environ.items() if not k.startswith('GIT_')}
            env.update(GIT_NO_REPLACE_OBJECTS='1', GIT_NO_LAZY_FETCH='1', GIT_OPTIONAL_LOCKS='0',
                       GIT_CONFIG_NOSYSTEM='1', GIT_CONFIG_GLOBAL=os.devnull, GIT_CONFIG_SYSTEM=os.devnull,
                       GIT_ALLOW_PROTOCOL='', GIT_TERMINAL_PROMPT='0')
            result = subprocess.run(['/usr/bin/git', '--no-replace-objects', '--literal-pathspecs',
                                     '-c', 'core.fsmonitor=false', *args],
                                    cwd='/proc/self/fd/' + str(walk.root), pass_fds=(walk.root,),
                                    env=env, capture_output=True, check=False)
            if result.returncode:
                raise ValueError('NEXT250 local origin verification failed')
            return result.stdout
        if (git('rev-parse', '--verify', base['commit'] + '^{commit}').decode().strip() != base['commit']
                or git('rev-parse', '--verify', base['commit'] + '^{tree}').decode().strip() != base['tree']):
            raise ValueError('NEXT250 published commit/tree differs')
        head = git('rev-parse', '--verify', 'HEAD^{commit}').decode().strip()
        git('merge-base', '--is-ancestor', base['commit'], head)
        provisional = b['provisional_input']
        if (not isinstance(provisional, dict) or set(provisional) != {'tree', 'qualification', 'expected_document'}
                or not re.fullmatch('[0-9a-f]{40}', str(provisional['tree']))
                or git('rev-parse', '--verify', provisional['tree'] + '^{tree}').decode().strip() != provisional['tree']):
            raise ValueError('NEXT250 exact qualified provisional tree missing')
        prefix = 'docs/provenance/r0002-next250-receiver/'
        roles = {
            'source_universe': ({'research/t20-v6-20261012/PUBLIC_PROJECTION_MANIFEST.json'}, {'published', 'qualified_provisional'}),
            'profile_provenance': ({'docs/provenance/v5-successors/SOURCE_MAP.json',
                                   'docs/provenance/v5-successors/PRESERVATION.json',
                                   'docs/provenance/v5-research-continuations/SOURCE_MAP.json',
                                   'docs/provenance/r0002-new250-receiver/CATALOG.json'}, {'published', 'qualified_provisional'}),
            'profile_checksum_manifest': ({
                'docs/project-closure/ar8r-v11/post-merge-proposals/pmr007-deep-a-ap/SHA256SUMS',
                'docs/project-closure/ar8r-v11/post-merge-proposals/pmr007-rounds11-20/SHA256SUMS'},
                {'published', 'qualified_provisional'}),
            'consumer_context': ({
                'docs/project-closure/reader-refactor-issue-35/CROSSWALK.json',
                'docs/project-closure/reader-refactor-issue-35/OWNER-MAP.json',
                'research/t20-v6-20261012/CURRENT_SOURCE_GRAPH.json'},
                {'published', 'qualified_provisional'}),
            'provisional_qualification': ({prefix + 'PROVISIONAL-QUALIFICATION.json'}, {'reviewed_receipt'}),
            'fallback_reachability': ({prefix + 'FALLBACK-REACHABILITY.json'}, {'reviewed_receipt'}),
            'reachability_acceptance': ({prefix + 'FALLBACK-ACCEPTANCE.json'}, {'reviewed_receipt'}),
        }
        policy = b['metadata_policy']
        if not isinstance(policy, dict) or not policy:
            raise ValueError('NEXT250 reviewed role/path/origin policy missing')
        for path, assignment in policy.items():
            self.safe_path(path)
            if (not isinstance(assignment, dict) or set(assignment) != {'role', 'origin'}
                    or assignment['role'] not in roles
                    or path not in roles[assignment['role']][0]
                    or assignment['origin'] not in roles[assignment['role']][1]):
                raise ValueError('NEXT250 unsupported metadata role/path/origin')
        seen = {}
        provisional_verified = False
        def metadata(spec, expected_roles):
            if not isinstance(spec, dict) or set(spec) != {'path', 'identity', 'role', 'origin'}:
                raise ValueError('NEXT250 metadata origin/role contract missing')
            path = self.safe_path(spec['path'])
            assignment = {'role': spec['role'], 'origin': spec['origin']}
            if spec['role'] not in expected_roles or policy.get(path) != assignment:
                raise ValueError('NEXT250 metadata role/origin assignment differs')
            identity = tuple(spec['identity'])
            if (len(identity) != 3 or not re.fullmatch('[0-9a-f]{40}', str(identity[0]))
                    or not re.fullmatch('[0-9a-f]{64}', str(identity[1]))
                    or type(identity[2]) is not int or identity[2] < 0):
                raise ValueError('NEXT250 metadata identity malformed')
            if path in seen and seen[path] != spec:
                raise ValueError('NEXT250 conflicting metadata specification')
            seen[path] = spec
            origin = spec['origin']
            if origin != 'reviewed_receipt':
                if origin == 'qualified_provisional' and not provisional_verified:
                    raise ValueError('NEXT250 provisional qualification not accepted')
                tree = base['tree'] if origin == 'published' else provisional['tree']
                expected = ('100644 blob ' + identity[0] + '\t' + path + '\0').encode()
                if git('ls-tree', '-z', tree, '--', path) != expected:
                    raise ValueError('NEXT250 metadata origin tree membership differs')
            body = walk.read(path, identity[2])
            if self.identity(body) != identity or walk.index({path}).get(path) != identity[0]:
                raise ValueError('NEXT250 metadata bytes/index differ')
            if spec['role'] == 'profile_checksum_manifest':
                text = body.decode('utf-8', errors='strict')
                rows = {}
                if not text or not text.endswith('\n'):
                    raise ValueError('NEXT250 checksum final newline missing')
                for line in text[:-1].split('\n'):
                    match = re.fullmatch(r'([0-9a-f]{64})  ([^\r\n]+)', line)
                    if match is None:
                        raise ValueError('NEXT250 checksum grammar differs')
                    digest, member = match.groups()
                    if (self.safe_path(member) != member or member in rows
                            or any(ord(c) < 32 or ord(c) == 127 for c in member)):
                        raise ValueError('NEXT250 checksum path duplicate/noncanonical')
                    rows[member] = digest
                return rows
            return self.parse_json(body)
        qualification = metadata(provisional['qualification'], {'provisional_qualification'})
        if (set(qualification) != {'verdict', 'published_base', 'tree', 'permitted_changes', 'independent_review_sha256'}
                or not _next250_exact(qualification, provisional['expected_document'])
                or qualification['verdict'] != 'QUALIFIED_PROVISIONAL_INPUT'
                or qualification['published_base'] != base or qualification['tree'] != provisional['tree']
                or not re.fullmatch('[0-9a-f]{64}', str(qualification['independent_review_sha256']))):
            raise ValueError('NEXT250 independent provisional qualification differs')
        changes = qualification['permitted_changes']
        if (not isinstance(changes, list) or any(not isinstance(row, dict)
                or set(row) != {'path', 'before_entry', 'after_entry'} for row in changes)):
            raise ValueError('NEXT250 provisional change contract differs')
        paths = [self.safe_path(row['path']) for row in changes]
        actual = git('diff-tree', '--no-commit-id', '--no-renames', '-r', '--name-only', '-z',
                     base['tree'], provisional['tree']).decode().rstrip('\0').split('\0')
        actual = [] if actual == [''] else actual
        if paths != sorted(set(paths)) or paths != sorted(actual):
            raise ValueError('NEXT250 provisional change domain differs')
        for row in changes:
            for key, tree in [('before_entry', base['tree']), ('after_entry', provisional['tree'])]:
                entry = git('ls-tree', '-z', tree, '--', row['path']).decode()
                if row[key] != entry:
                    raise ValueError('NEXT250 provisional change identity differs')
        provisional_verified = True
        universe = metadata(b['source_universe'], {'source_universe'})
        self.validate_rows(universe['objects'])
        profiles = b['separation_profiles']
        required = {'original1180': 1180, 'public123': 123, 'current250': 250, 'historical_providers': None}
        if set(profiles) != set(required):
            raise ValueError('NEXT250 known historical/current separation contract required')
        for name, count in required.items():
            spec = profiles[name]
            if set(spec) != {'rows', 'metadata_inputs'} or not spec['metadata_inputs']:
                raise ValueError('NEXT250 profile provenance missing')
            for item in spec['metadata_inputs']:
                metadata(item, {'profile_provenance', 'source_universe', 'profile_checksum_manifest'})
            profile = spec['rows']
            if not isinstance(profile, list) or not profile or (count is not None and len(profile) != count):
                raise ValueError('NEXT250 historical profile count differs')
            keys = set()
            for row in profile:
                if set(row) != {'key', 'paths', 'source_identities'} or row['key'] in keys:
                    raise ValueError('NEXT250 historical profile row differs')
                keys.add(row['key'])
                if not row['paths'] or not row['source_identities']:
                    raise ValueError('NEXT250 historical profile identity missing')
                paths = {self.safe_path(p) for p in row['paths']}
                identities = set(row['source_identities'])
                if any(not re.fullmatch('[0-9a-f]{64}', x) for x in identities):
                    raise ValueError('NEXT250 historical source identity malformed')
                if self.paths.intersection(paths) or self.ids.intersection(identities):
                    raise ValueError('NEXT250 overlaps known historical/current profile ' + name)
        contexts = b['consumer_contexts']
        context_paths = {
            'crosswalk': 'docs/project-closure/reader-refactor-issue-35/CROSSWALK.json',
            'owner_map': 'docs/project-closure/reader-refactor-issue-35/OWNER-MAP.json',
            'source_graph': 'research/t20-v6-20261012/CURRENT_SOURCE_GRAPH.json'}
        if not isinstance(contexts, dict) or set(contexts) != set(context_paths):
            raise ValueError('NEXT250 complete consumer contexts required')
        documents = {}
        for key, path in context_paths.items():
            if not isinstance(contexts[key], dict) or contexts[key].get('path') != path:
                raise ValueError('NEXT250 consumer context path differs')
            documents[key] = metadata(contexts[key], {'consumer_context'})
        # Full byte identities above authenticate the semantic edition. Existing
        # owner/graph/reader validators retain their separate semantic obligations.
        sources = documents['crosswalk'].get('sources')
        if not isinstance(sources, dict):
            raise ValueError('NEXT250 reader source map differs')
        projection = {}
        for key, row in sources.items():
            if not isinstance(row, dict):
                raise ValueError('NEXT250 reader source row differs')
            if row.get('path') in self.paths:
                member = self.members[row['path']]
                if (set(row) != {'path', 'sha256', 'read_scope'}
                        or row['sha256'] != member['sha256']
                        or not isinstance(row['read_scope'], str) or not row['read_scope']):
                    raise ValueError('NEXT250 selected reader identity/scope differs')
                projection[key] = row
        if not isinstance(b['reader_rows'], dict) or not _next250_exact(projection, b['reader_rows']):
            raise ValueError('NEXT250 selected reader projection differs')
        # This logic/input edition predates final binding insertion. Final executable
        # consumer identity is authenticated by the existing external owner boundary.
        logic = b['consumer_logic_sha256']
        if not isinstance(logic, str) or not re.fullmatch('[0-9a-f]{64}', logic):
            raise ValueError('NEXT250 reviewed consumer logic edition missing')
        input_edition = {'published_base': base, 'provisional_tree': provisional['tree'],
                         'source_universe': b['source_universe'], 'separation_profiles': profiles,
                         'consumer_contexts': contexts, 'reader_rows': b['reader_rows']}
        receipt = metadata(b['fallback_reachability'], {'fallback_reachability'})
        if (set(receipt) != {'status', 'paths', 'consumers', 'input_edition', 'consumer_logic_sha256', 'evidence'}
                or receipt['status'] != 'INDEPENDENTLY_VERIFIED_FALLBACK_ONLY'
                or receipt['paths'] != sorted(self.paths)
                or receipt['consumers'] != ['resolver', 'projection', 'reader', 'references']
                or not _next250_exact(receipt['input_edition'], input_edition)
                or receipt['consumer_logic_sha256'] != logic):
            raise ValueError('NEXT250 reachability semantic edition differs')
        evidence = receipt['evidence']
        expected_pairs = {(path, consumer) for path in self.paths for consumer in receipt['consumers']}
        if not isinstance(evidence, list) or len(evidence) != len(expected_pairs):
            raise ValueError('NEXT250 finite predicate/context evidence missing')
        pairs = set()
        for row in evidence:
            if (not isinstance(row, dict) or set(row) != {'path', 'consumer', 'predicate_record', 'context_record'}
                    or not isinstance(row['predicate_record'], str) or not row['predicate_record'].strip()
                    or not isinstance(row['context_record'], str) or not row['context_record'].strip()):
                raise ValueError('NEXT250 finite predicate/context record differs')
            pairs.add((row['path'], row['consumer']))
        if pairs != expected_pairs:
            raise ValueError('NEXT250 finite reachability domain differs')
        acceptance = metadata(b['reachability_acceptance'], {'reachability_acceptance'})
        expected_acceptance = {'verdict': 'ACCEPT_FINITE_FALLBACK_EVIDENCE',
                               'receipt': b['fallback_reachability'], 'input_edition': input_edition,
                               'consumer_logic_sha256': logic}
        if not _next250_exact(acceptance, expected_acceptance):
            raise ValueError('NEXT250 independently accepted receipt/edition differs')
        if set(seen) != set(policy):
            raise ValueError('NEXT250 unused or unclassified metadata policy paths')
        return head

    def source_bytes(self, root, path):
        path = self.safe_path(path)
        if path not in self.members:
            raise ValueError('path outside finite provider')
        return self.snapshot(root)[0][path]

    def public_bytes(self, root, row):
        path = self.safe_path(row.get('repository_path'))
        if path not in self.members or not _next250_exact(row, self.members[path]['public']):
            raise ValueError('provider complete public row differs')
        return self.source_bytes(root, path)

    def reference_candidate(self, root, path):
        # Invoked only at one physical-existence leaf, never across candidates.
        normalized = os.path.normpath(path)
        if os.path.isabs(normalized):
            normalized = os.path.relpath(normalized, os.path.abspath(root))
        if normalized not in self.paths:
            return None
        try:
            self.source_bytes(root, self.safe_path(path))
        except (ValueError, OSError):
            return False
        return True

    def reader_source(self, root, key, row):
        path = self.safe_path(row.get('path'))
        expected = self.binding.get('reader_rows')
        if (path not in self.paths or expected is None or key not in expected
                or not _next250_exact(row, expected[key])):
            raise ValueError('NEXT250 reader key/path/hash/scope differs')
        return self.source_bytes(root, path)

